// Headroom-native components (MIDI / instruments) registered outside the generated table.
const ComponentSchema* findExtraComponent(int32_t table_id) noexcept;
std::span<const ComponentSchema> extraComponents() noexcept;
// Headroom studio units (the Cabinet, 900100), registered in src/dsp/CabinetUnit.cpp.
const ComponentSchema* findStudioComponent(int32_t table_id) noexcept;
std::span<const ComponentSchema> studioComponents() noexcept;

inline const ComponentSchema* findByTableId(int32_t table_id) noexcept {
    for (const auto& c : kAllComponents) {
        if (c.table_id == table_id) return &c;
    }
    if (const auto* s = findStudioComponent(table_id)) return s;
    return findExtraComponent(table_id);
}

constexpr const ComponentSchema* findByReferenceName(std::string_view ref_name) noexcept {
    for (const auto& c : kAllComponents) {
        if (c.reference_name == ref_name) return &c;
    }
    return nullptr;
}

